package app

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View renders the interface: header, title line, viewport, footer (Rule 124).
// An open overlay replaces the whole thing.
func (a *App) View() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceBackground(theme.ColorBackground))
	}

	inner := a.renderHeader() + "\n" + a.renderTitleLine() + "\n" + a.renderBody()
	if footer := a.renderViewFooter(); footer != "" {
		inner += "\n" + footer
	}

	return lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceBackground(theme.ColorBackground))
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.View()
	}

	innerWidth := a.viewport.Width - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return a.overlaySuggestions(body)
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
// reader oriented where a top border would draw the top of a nonexistent box.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitle(title, a.width)
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). The default is framed.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}
package app

import (
	"fmt"
	"strings"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
)

// minListHeight is the smallest usable viewport height that holds a list: one
// row and the bottom rule.
const minListHeight = 2

// noticeEmptyLine is the warning for an enter on a line with nothing typed.
const noticeEmptyLine = "Type a name or choose one"

// refreshSuggestions ranks the registry for the text in the command line. The
// first row is highlighted when a query is typed (a bare ":" is none) and
// something is found; otherwise nothing is, so enter cannot run a command nobody chose.
func (a *App) refreshSuggestions() {
	a.suggestions = a.suggester.Suggest(a.commandInput.Value())
	a.sugOffset = 0
	a.sugCursor = -1
	if a.suggestions.Query != "" && len(a.suggestions.Entries) > 0 {
		a.sugCursor = 0
	}
}

// resetSuggestions forgets the list; the command line is closed or about to be
// reopened empty.
func (a *App) resetSuggestions() {
	a.suggestions = command.Suggestions{}
	a.sugCursor = -1
	a.sugOffset = 0
	a.sugNotice = ""
}

// highlightedEntry returns the highlighted row, if there is one.
func (a *App) highlightedEntry() (command.Entry, bool) {
	if a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Entries) {
		return command.Entry{}, false
	}
	return a.suggestions.Entries[a.sugCursor], true
}

// canComplete reports whether tab has something to complete: a highlighted
// row, at the command stage (an argument is typed, not chosen).
func (a *App) canComplete() bool {
	_, ok := a.highlightedEntry()
	return ok && a.suggestions.Stage == command.StageCommand
}

// nothingToRunNotice is the warning for an enter with no highlighted row.
func (a *App) nothingToRunNotice() string {
	q := a.suggestions.Query
	if q == "" {
		return noticeEmptyLine
	}
	return fmt.Sprintf("%q is not a view or a command", q)
}

// completeHighlighted writes the highlighted row's name into the line, with a
// trailing space when the command takes an argument. It runs nothing.
func (a *App) completeHighlighted() {
	if !a.canComplete() {
		return
	}
	entry, _ := a.highlightedEntry()
	text := entry.Name
	if entry.TakesArg() {
		text += " "
	}
	a.commandInput.SetValue(text)
	a.commandInput.CursorEnd()
	a.refreshSuggestions()
}

// listUsable is the number of viewport content lines the list may cover.
func (a *App) listUsable() int {
	if a.frameless() {
		return a.viewport.Height
	}
	return a.viewport.Height - 1 // the bottom border stays
}

// listVisible is how many suggestion rows are drawn; 0 means no list.
func (a *App) listVisible() int {
	usable := a.listUsable()
	if usable < minListHeight {
		return 0
	}
	return cmdsuggest.VisibleRows(len(a.suggestions.Entries), usable)
}

// moveHighlight moves the highlight by delta rows without wrapping. With no
// highlighted row, down takes the first visible row and up the last.
func (a *App) moveHighlight(delta int) {
	n := len(a.suggestions.Entries)
	if n == 0 {
		return
	}
	visible := a.listVisible()
	switch {
	case a.sugCursor < 0 && delta > 0:
		a.sugCursor = a.sugOffset
	case a.sugCursor < 0:
		a.sugCursor = min(n-1, a.sugOffset+max(visible, 1)-1)
	default:
		a.sugCursor = max(min(a.sugCursor+delta, n-1), 0)
	}
	a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, visible)
}

// keepHighlightVisible re-windows the list after the viewport changed size.
func (a *App) keepHighlightVisible() {
	a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, a.listVisible())
}

// suggestionLines renders the list and its bottom rule, or nil when the command
// line is closed or the viewport is too short for a list.
func (a *App) suggestionLines() []string {
	visible := a.listVisible()
	if !a.commandMode || visible == 0 {
		return nil
	}
	rows := make([]cmdsuggest.Row, len(a.suggestions.Entries))
	for i, e := range a.suggestions.Entries {
		rows[i] = cmdsuggest.Row{Entry: e, Current: e.Kind == command.KindView && e.Name == string(a.currentView)}
	}
	frame := cmdsuggest.FrameJoined
	if a.frameless() {
		frame = cmdsuggest.FrameClosed
	}
	return cmdsuggest.Render(cmdsuggest.Input{
		Rows:    rows,
		Total:   a.suggestions.Total,
		Query:   a.suggestions.Query,
		Cursor:  a.sugCursor,
		Offset:  a.sugOffset,
		Notice:  a.sugNotice,
		Width:   a.viewport.Width,
		Visible: visible,
		Frame:   frame,
	})
}

// overlaySuggestions replaces the top lines of the viewport with the list.
// Whole lines are swapped, so no styled text is ever cut.
func (a *App) overlaySuggestions(body string) string {
	list := a.suggestionLines()
	if len(list) == 0 {
		return body
	}
	lines := strings.Split(body, "\n")
	copy(lines, list)
	return strings.Join(lines, "\n")
}
package app

import (
	"log"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/ui/about"
	"github.com/anthnel/devdesk/internal/ui/agentusageview"
	"github.com/anthnel/devdesk/internal/ui/configuration"
	"github.com/anthnel/devdesk/internal/ui/containers"
	"github.com/anthnel/devdesk/internal/ui/dashboard"
	"github.com/anthnel/devdesk/internal/ui/filebrowser"
	"github.com/anthnel/devdesk/internal/ui/forge/auth"
	"github.com/anthnel/devdesk/internal/ui/forge/explorer"
	"github.com/anthnel/devdesk/internal/ui/jobsview"
	"github.com/anthnel/devdesk/internal/ui/netdiag"
	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
	"github.com/anthnel/devdesk/internal/ui/security"
	"github.com/anthnel/devdesk/internal/ui/status"
	"github.com/anthnel/devdesk/internal/ui/templates"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
	"github.com/anthnel/devdesk/internal/ui/workspaces"
)

// handleCommandMode handles a key while the command line owns the keyboard.
// Every key first clears the warning on the list's bottom rule: it lasts until
// the next keystroke, with no timer.
func (a *App) handleCommandMode(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	a.sugNotice = ""

	switch msg.Type {
	case tea.KeyEsc:
		return a, a.closeCommandLine()
	case tea.KeyTab:
		a.completeHighlighted()
		return a, nil
	case tea.KeyShiftTab:
		return a, nil
	case tea.KeyUp:
		a.moveHighlight(-1)
		return a, nil
	case tea.KeyDown:
		a.moveHighlight(1)
		return a, nil
	case tea.KeyEnter:
		return a.runCommand()
	}
	return a.handleCommandInput(msg)
}

// handleCommandInput feeds an ordinary key to the input and ranks the registry
// again for the new text.
func (a *App) handleCommandInput(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	before := a.commandInput.Value()
	a.commandInput, cmd = a.commandInput.Update(msg)
	if a.commandInput.Value() != before {
		a.refreshSuggestions()
	}
	return a, cmd
}

// closeCommandLine leaves command mode and asks for the re-layout that gives
// the row back to the inactive prompt. The list goes with the line.
func (a *App) closeCommandLine() tea.Cmd {
	a.commandMode = false
	a.commandInput.Blur()
	a.resetSuggestions()
	return a.requestResize()
}

// runCommand executes the highlighted row, or at the argument stage the text
// as typed. With nothing to run it says so on the list's bottom rule and
// leaves the line open.
func (a *App) runCommand() (tea.Model, tea.Cmd) {
	input := a.commandInput.Value()
	if a.suggestions.Stage != command.StageArgument {
		entry, ok := a.highlightedEntry()
		if !ok {
			a.sugNotice = a.nothingToRunNotice()
			return a, nil
		}
		input = entry.Name
	}

	cmd := command.ParseCommand(input)

	switch cmd.Type {
	case command.CommandQuit:
		a.resetSuggestions()
		return a, tea.Quit

	case command.CommandView:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetSuggestions()
		a.resetSelectionModeFor(cmd.View)
		return a, a.switchView(cmd.View)

	case command.CommandContext:
		a.commandMode = false
		a.commandInput.Blur()
		a.resetSuggestions()
		if len(cmd.Args) > 0 {
			// Create/switch to a named context
			return a, a.switchContext(cmd.Args[0])
		}
		// No args -> open the interactive modal
		return a, a.listContexts()
	}

	return a, nil
}

// resetSelectionModeFor takes a view out of selection mode before switching to
// it, by dropping it so it is rebuilt normally.
//
// Only the workspaces view is lent now. The images view was the other one — the
// security form borrowed it to pick a scan target — and it could not simply be
// dropped, because it holds scan results worth keeping; it took a
// ResetSelectionMsg instead. That whole path went with the form (phase 3).
//
// The security and network views are dropped too, when they are showing what
// another view sent them: workspaces and images set the security view's
// OriginView, and status's H sets netdiag's. What such a view shows is that
// view's detail, not its own state. Naming the view asks for the view — its
// inventory, or a blank form — and keeping the detail answered with the same
// thing again, with esc leading back to where it came from.
//
// A view reached by name has no origin and is kept, like every other view's
// state across a switch.
func (a *App) resetSelectionModeFor(view command.ViewType) {
	switch view {
	case command.ViewWorkspaces:
		delete(a.views, view)
	case command.ViewFiles:
		// A picker left behind — the user typed a command instead of choosing —
		// answers a borrower; the name asks for the browser.
		if held, ok := a.views[view].(filebrowser.Model); ok && held.Picking() {
			delete(a.views, view)
		}
	case command.ViewSecurity:
		if held, ok := a.views[view].(security.Model); ok && held.OriginView != "" {
			delete(a.views, view)
		}
	case command.ViewNetdiag:
		// The same rule, with one precaution the security view does not need: a
		// diagnostic sent from status may still be walking its stages, and
		// dropping the view would discard that run without a word. A run in
		// flight keeps its view; esc on it still returns to status.
		if held, ok := a.views[view].(*netdiag.Model); ok && held.OriginView != "" && !held.Running() {
			delete(a.views, view)
		}
	}
}

// switchView changes the current view
func (a *App) switchView(view command.ViewType) tea.Cmd {
	if view != a.currentView {
		if cmd, ok := a.settleCurrentView(); !ok {
			return cmd
		}
	}

	// Lazy loading of views
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + a WindowSizeMsg to force the resize, plus the snapshot of
	// work in progress: the view was kept up to date for as long as it
	// existed, but a view built just now was not there for anything that had
	// already started.
	return tea.Batch(newView.Init(), a.requestResize(), a.sendJobsTo(view))
}

// settleCurrentView gives the view being left the chance to write down what it
// holds, and lets it refuse to be left.
//
// A view that does not implement LeavingView is left without ceremony, which is
// every view but two: the configuration form keeps a value in a widget rather
// than in the model until a key moves the cursor, and the agent usage view has a
// live poll to stop.
//
// Returning false keeps the current view *and* whatever it wants to say about
// why — the caller passes that Cmd on rather than the switch it did not make.
func (a *App) settleCurrentView() (tea.Cmd, bool) {
	current, exists := a.views[a.currentView]
	if !exists {
		return nil, true
	}
	leaver, implements := current.(LeavingView)
	if !implements {
		return nil, true
	}
	settled, cmd, ok := leaver.Leave()
	a.views[a.currentView] = settled
	return cmd, ok
}

// createView creates a view (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	case command.ViewAgentUsage:
		a.views[view] = agentusageview.New(a.config)
	case command.ViewConfiguration:
		a.views[view] = configuration.New(a.config, a.mcpFacts())
	case command.ViewJobs:
		a.views[view] = jobsview.New(a.config, a.currentContext)
	case command.ViewTemplates:
		a.views[view] = templates.New(a.config, a.sharedState.Secrets.Storage)
	case command.ViewAbout:
		a.views[view] = about.New(a.config)
	case command.ViewFiles:
		a.views[view] = filebrowser.New(a.config)
	case command.ViewViewer:
		// Empty: the viewer is normally installed with its source by
		// handleViewerOpenRequest, and this case exists so the router can build
		// one like any other view — which is what the contract test does.
		a.views[view] = uiviewer.New(a.config)
	}
	// Built after the detection landed, it was not there to receive it.
	a.sendScanToolsTo(view)
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, a.sharedState.Secrets, a.sharedState.SecretNotices)
	if a.sharedState.IsAuthenticated {
		authView.SetAuth(a.sharedState.Forge, a.sharedState.CurrentUser)
	}
	return authView
}

